UPDATE public.tn_areas SET center=ST_SetSRID(ST_MakePoint(77.60913,9.56014),4326)::geography WHERE district_slug='virudhunagar' AND name='Srivilliputhur';
UPDATE public.tn_areas SET center=ST_SetSRID(ST_MakePoint(77.94185,9.32268),4326)::geography WHERE district_slug='virudhunagar' AND name='Sattur';
CREATE INDEX IF NOT EXISTS tn_areas_center_idx ON public.tn_areas USING gist(center);

-- Nearest seeded area (within 25 km) decides district+area; otherwise nearest district centre.
CREATE OR REPLACE FUNCTION public.nearest_location(_lat double precision, _lng double precision)
RETURNS TABLE(district_slug text, district_name jsonb, area_id bigint, area_name text, area_name_ta text, distance_km double precision)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$
  WITH p AS (SELECT ST_SetSRID(ST_MakePoint(_lng,_lat),4326)::geography g),
  a AS (SELECT x.id, x.district_slug, x.name, x.name_ta, ST_Distance(x.center, p.g)/1000 km
        FROM public.tn_areas x, p WHERE x.center IS NOT NULL ORDER BY x.center <-> p.g LIMIT 1),
  d AS (SELECT t.slug, t.name_i18n, ST_Distance(t.center, p.g)/1000 km FROM public.tn_districts t, p ORDER BY t.center <-> p.g LIMIT 1)
  SELECT t.slug, t.name_i18n, a.id, a.name, a.name_ta, a.km
    FROM a JOIN public.tn_districts t ON t.slug = a.district_slug WHERE a.km <= 25
  UNION ALL
  SELECT d.slug, d.name_i18n, NULL::bigint, NULL, NULL, d.km FROM d
    WHERE NOT EXISTS (SELECT 1 FROM a WHERE a.km <= 25)
  LIMIT 1;
$$;
GRANT EXECUTE ON FUNCTION public.nearest_location(double precision,double precision) TO anon, authenticated;
-- plain lat/lng for clients (map centring)
ALTER TABLE public.tn_areas ADD COLUMN IF NOT EXISTS lat double precision GENERATED ALWAYS AS (ST_Y(center::geometry)) STORED, ADD COLUMN IF NOT EXISTS lng double precision GENERATED ALWAYS AS (ST_X(center::geometry)) STORED;
COMMIT;
